    NewsItem(Icons.history, 'Déjà répondu ? Réponse immédiate',
        'Reposez une question, même autrement : Tontolo reprend sa réponse aussitôt, sans quota, et l\'indique (« Déjà répondu le … »). Jamais pour l\'actualité ni une question personnelle. Régénérer en donne une nouvelle. Tout reste sur l\'appareil.',
        'Already answered? Instant answer', 'Ask a question again, even worded differently: Tontolo reuses its answer at once, with no quota used, and says so (“Already answered on …”). Never for news or a personal question. Regenerate gives a fresh one. Everything stays on the device.',
        mg: 'Efa novaliana? Valiny avy hatrany', mgText: 'Avereno ny fanontaniana, na amin\'ny teny hafa aza: averin\'i Tontolo avy hatrany ny valiny, tsy mandany quota, ary lazainy izany (« Efa novaliana tamin\'ny … »). Tsy atao mihitsy ho an\'ny vaovao na fanontaniana manokana. Ny « Avereno » no manome vaovao. Ao amin\'ny fitaovana daholo ny zava-drehetra.'),
    NewsItem(Icons.hub_outlined, 'Plus de fournisseurs, mode avancé plus souple',
        'Cerebras, SambaNova, GitHub Models, Together gratuits ; Kimi, Qwen, Perplexity payants. En mode avancé : vos propres fournisseurs compatibles OpenAI (testés et protégés), vos enchaînements de modèles, des fournisseurs exclus, des délais réglables, l\'export des réglages sans clé.',
        'More providers, more flexible advanced mode', 'Cerebras, SambaNova, GitHub Models, Together free; Kimi, Qwen, Perplexity paid. In advanced mode: your own OpenAI-compatible providers (tested and protected), your model chains, excluded providers, adjustable timeouts, settings export without keys.',
        mg: 'Mpamatsy maro kokoa, fomba mandroso malefaka kokoa', mgText: 'Cerebras, SambaNova, GitHub Models, Together maimaim-poana; Kimi, Qwen, Perplexity mandoa vola. Amin\'ny fomba mandroso: ny mpamatsinao manokana mifanaraka amin\'ny OpenAI (voazaha sy voaaro), ny filaharan\'ny modely, mpamatsy tsy ampiasaina, fe-potoana azo ovaina, famoahana ny kirakira tsy misy fanalahidy.'),
  ],
  '0.5.6': [
    NewsItem(Icons.quiz_outlined, 'Tontolo vous pose les bonnes questions',
        'Pour une demande ouverte (« Écris un rapport Word sur la pollution »), Tontolo demande d\'abord le public et la longueur, en puces à toucher. Touchez vos choix : le document est fait sur mesure.',
        'Tontolo asks you the right questions', 'For an open request (“Write a Word report about pollution”), Tontolo first asks who it is for and how long, as chips to tap. Tap your choices: the document is made to measure.',
        mg: 'Manontany tsara i Tontolo', mgText: 'Raha misy fangatahana malalaka (« Manorata tatitra Word momba ny fandotoana »), anontanian\'i Tontolo aloha hoe ho an\'iza sy ny halavany, amin\'ny safidy tsindriana. Tsindrio ny safidinao: vita araka ny tianao ilay antontan-taratasy.'),
    NewsItem(Icons.speed_outlined, 'Plus solide, plus rapide',
        'Un chapitre de livre qui ne compile pas est simplifié au lieu de tout faire échouer. Les longues discussions s\'ouvrent sur les 120 derniers messages. Tontolo mesure la vitesse réelle des modèles et favorise les plus rapides.',
        'Sturdier and faster', 'A book chapter that does not compile is simplified instead of failing everything. Long chats open on the last 120 messages. Tontolo measures the models\' real speed and favors the fastest.',
        mg: 'Matanjaka sy haingana kokoa', mgText: 'Toko tsy mety dia tsorina fa tsy mampijanona ny boky manontolo. Misokatra amin\'ny hafatra 120 farany ny resaka lava. Refesin\'i Tontolo ny hafainganan\'ny modely ary ny haingana no ankasitrahana.'),
  ],
  '0.5.5': [
    NewsItem(Icons.history_edu_outlined, 'Corrigez vos fichiers en une phrase',
        'Après une carte mentale ou un document, dites simplement « excellent mais des vraies citations » ou « plus court » : Tontolo corrige ce fichier et le livre en nouvelle version (-v2, -v3), sans écraser la précédente.',
        'Fix your files in one sentence', 'After a mind map or a document, just say “great but with real quotes” or “shorter”: Tontolo fixes that file and delivers a new version (-v2, -v3) without overwriting the previous one.',
        mg: 'Ovay amin\'ny fehezanteny iray ny rakitrao', mgText: 'Aorian\'ny sarintsaina na antontan-taratasy, lazao fotsiny hoe « tsara fa ampio ohatra tena izy » na « fohy kokoa »: ahitsin\'i Tontolo io rakitra io ary omeny dikan-teny vaovao (-v2, -v3) tsy mamafa ilay teo aloha.'),
    NewsItem(Icons.format_quote_outlined, 'Plus de citations inventées',
        'Quand vous demandez des citations, seules celles dont le modèle est certain sont entre guillemets ; les autres sont marquées « ≈ » pour être vérifiées. Les balises d\'outils n\'apparaissent plus dans les réponses.',
        'No more invented quotes', 'When you ask for quotes, only those the model is sure of are in quotation marks; others are marked “≈” to be checked. Tool tags no longer show up in answers.',
        mg: 'Tsy misy teny nampiana intsony', mgText: 'Rehefa mangataka teny nalaina ianao, ireo azon\'ny modely antoka ihany no apetraka ao anaty tondro; ny hafa dia misy marika « ≈ » mba hojerena. Tsy miseho intsony ao amin\'ny valiny ny marika fitaovana.'),
  ],
  '0.5.4': [
    NewsItem(Icons.notifications_active_outlined, 'Qui travaille, qui vous attend',
        'Une pastille verte indique une discussion en cours sur cet appareil, une pastille bleue sur un autre appareil, une pastille orange « ? » qu\'elle attend votre réponse. Le menu porte un badge, et Tontolo vous prévient si une question vous attend ailleurs.',
        'Who is working, who is waiting', 'A green dot marks a chat running on this device, a blue one on another device, an orange “?” one waiting for your answer. The menu shows a badge, and Tontolo tells you if a question is waiting for you elsewhere.',
        mg: 'Iza no miasa, iza no miandry', mgText: 'Ny teboka maitso dia manondro resaka mandeha amin\'ity fitaovana ity, ny manga amin\'ny fitaovana hafa, ny volomboasary « ? » kosa miandry ny valinao. Misy marika ny menio, ary mampahafantatra anao i Tontolo raha misy fanontaniana miandry anao any amin\'ny hafa.'),
  ],
  '0.5.3': [
    NewsItem(Icons.menu_book_outlined, 'Des livres de 200 pages',
        'Demandez « Génère un livre de 200 pages sur… » : Tontolo établit le plan, rédige les chapitres en parallèle, compile le PDF et vous le livre. Chaque chapitre apparaît dans « Résultats intermédiaires » dès qu\'il est écrit.',
        'Books of 200 pages', 'Ask “Generate a 200-page book about…”: Tontolo plans it, writes the chapters in parallel, builds the PDF and delivers it. Each chapter shows up in “Intermediate results” as soon as it is written.',
        mg: 'Boky 200 pejy', mgText: 'Angataho hoe « Mamorona boky 200 pejy momba… »: manao drafitra i Tontolo, manoratra ny toko miaraka, manamboatra ny PDF ary manome azy aminao. Miseho ao amin\'ny « Vokatra mpanelanelana » avy hatrany ny toko tsirairay.'),
    NewsItem(Icons.task_alt_outlined, 'Fini la demande « écrire un fichier ? »',
        'Les fichiers demandés sont créés et livrés directement. Le sélecteur Général / Apprendre / Agent ne montre plus que le nom du mode actif.',
        'No more “may I write a file?”', 'Requested files are created and delivered directly. The General / Learn / Agent switch now shows only the active mode\'s name.',
        mg: 'Tsy misy fangatahana « hanoratra rakitra? » intsony', mgText: 'Foronina sy omena mivantana ny rakitra angatahana. Ny anaran\'ny fomba mavitrika ihany no aseho ao amin\'ny Ankapobeny / Mianatra / Agent.'),
    NewsItem(Icons.photo_library_outlined, 'Un poster pour chaque version',
        'Cette fenêtre montre maintenant un poster illustré de la version, avec le changement majeur en exemple. Touchez-le pour l\'agrandir ou le partager.',
        'A poster for each version', 'This window now shows an illustrated poster of the version, with the major change as an example. Tap it to enlarge or share it.',
        mg: 'Sary fanehoana isaky ny dikan-teny', mgText: 'Mampiseho sary fanehoana misy sary ny dikan-teny ity varavarankely ity, miaraka amin\'ny fanovana lehibe ho ohatra. Tsindrio izy hanalehibe na hizara azy.'),
  ],
  '0.5.2': [
    NewsItem(Icons.waving_hand_outlined, 'Un accueil qui vous salue',
        'Chaque nouvelle discussion vous accueille selon l\'heure, avec votre prénom (Réglages › Personnalisation), et propose des idées qui changent, dont la reprise de votre dernière discussion.',
        'A welcome that greets you', 'Each new chat greets you according to the time of day, with your first name (Settings › Personalization), and suggests changing ideas, including resuming your last chat.',
        mg: 'Fandraisana miarahaba anao', mgText: 'Miarahaba anao araka ny ora ny resaka vaovao tsirairay, miaraka amin\'ny anaranao (Kirakira › Fanamboarana manokana), ary manolotra hevitra miova, anisan\'izany ny fanohizana ny resaka farany.'),
    NewsItem(Icons.cleaning_services_outlined, 'Moins de place utilisée',
        'Les caches sont regroupés et nettoyés tout seuls ; les anciennes mises à jour ne s\'accumulent plus. Réglages › Avancé › Stockage montre la place occupée.',
        'Less storage used', 'Caches are grouped and cleaned automatically; old updates no longer pile up. Settings › Advanced › Storage shows what uses space.',
        mg: 'Toerana kely kokoa', mgText: 'Ampivondronina sy diovina ho azy ny cache; tsy miangona intsony ny fanavaozana taloha. Ny Kirakira › Mandroso › Fitahirizana no mampiseho ny toerana ampiasaina.'),
  ],
  '0.5.1': [
    NewsItem(Icons.smart_toy_outlined, 'Mode Agent et tâches complexes',
        'Nouvel onglet Agent avec Chercheur, Développeur, Rédacteur et Analyste, gratuits par défaut. Une grande tâche est découpée en étapes : plusieurs modèles travaillent en même temps, ou Tontolo avance pas à pas avec « Continuer ».',
        'Agent mode and complex tasks', 'New Agent tab with Researcher, Developer, Writer and Analyst, free by default. Big tasks are split into steps: several models work at once, or Tontolo goes step by step with “Continue”.',
        mg: 'Fomba Agent sy asa sarotra', mgText: 'Tabilao Agent vaovao miaraka amin\'ny Mpikaroka, Mpamorona rindrankajy, Mpanoratra ary Mpandalina, maimaim-poana. Zarazaraina ho dingana ny asa lehibe: modely maromaro miara-miasa, na mandroso tsikelikely amin\'ny « Tohizo ».'),
    NewsItem(Icons.info_outline, 'Modèles et générateurs expliqués',
        'Touchez ⓘ pour voir la fiche d\'un modèle (coût, contexte, capacités, scores). Le badge Agent signale ceux qui utilisent des outils. « Générateurs » liste les créateurs d\'images, de vidéos et de sons.',
        'Models and generators explained', 'Tap ⓘ to see a model\'s sheet (cost, context, capabilities, scores). The Agent badge marks tool-using models. “Generators” lists image, video and sound creators.',
        mg: 'Modely sy mpamorona hazavaina', mgText: 'Tsindrio ny ⓘ hahitana ny antsipirian\'ny modely (sarany, contexte, fahaizana, isa). Ny marika Agent no manondro ireo mampiasa fitaovana. « Mpamorona » no mitanisa ireo mamorona sary, horonan-tsary ary feo.'),
    NewsItem(Icons.devices, 'Continuez partout, même en arrière-plan',
        'Sur Android, la réponse continue quand vous quittez l\'app. Vos créations et les tâches en cours apparaissent sur vos autres appareils. Plusieurs fichiers arrivent dans un .zip.',
        'Continue anywhere, even in the background', 'On Android, answers keep going when you leave the app. Your creations and running tasks show up on your other devices. Several files arrive in a .zip.',
        mg: 'Tohizo na aiza na aiza', mgText: 'Amin\'ny Android, mitohy ny valiny na dia mivoaka ny app aza ianao. Hita amin\'ny fitaovanao hafa ny famoronanao sy ny asa mandeha. Ao anaty .zip ny rakitra maromaro.'),
    NewsItem(Icons.terminal, 'Bureau : navigateur et terminal',
        'Sur Linux, choisissez un dossier de travail : l\'agent lit et modifie vos fichiers avec votre accord, lance des commandes confirmées et pilote un navigateur. Sur tablette, un panneau navigateur s\'ouvre à côté de la discussion.',
        'Desktop: browser and terminal', 'On Linux, pick a work folder: the agent reads and edits your files with your approval, runs confirmed commands and drives a browser. On tablets, a browser panel opens next to the chat.',
        mg: 'Solosaina: mpitety sy terminal', mgText: 'Amin\'ny Linux, misafidiana lahatahiry iasana: mamaky sy manova ny rakitrao ny agent raha ekenao, mandefa baiko voamarina ary mitarika mpitety. Amin\'ny tablette, misokatra eo akaikin\'ny resaka ny mpitety.'),
  ],
  '0.5.0': [
    NewsItem(Icons.forum_outlined, 'Des discussions bien séparées',
        'Les dossiers rangent vos discussions sans mélanger leurs réponses. Les souvenirs explicites restent partagés et leur origine est conservée.',
        'Separate chat contexts', 'Folders organize chats without mixing their answers. Explicit memories stay shared and keep their origin.',
        mg: 'Resaka voasaraka tsara', mgText: 'Mandamina ny resaka ny lahatahiry fa tsy mampifangaro ny valiny. Voatahiry ny niavian’ny fahatsiarovana nangatahanao.'),
    NewsItem(Icons.movie_outlined, 'Animez la bonne image',
        'Après une image, demandez « anime-la ». Tontolo reprend cette image ; si elle manque ou a échoué, il vous le dit. Une nouvelle vidéo peut aussi partir du texte seul.',
        'Animate the right image', 'After creating an image, ask “animate it”. Tontolo uses that image or reports that it is missing. New videos can also start from text alone.',
        mg: 'Ampihetsiho ny sary', mgText: 'Rehefa vita ny sary, angataho hoe « ampihetsiho ». Io sary io no ampiasaina, na ampandrenesina ianao raha tsy misy izany.'),
  ],
  '0.4.7': [
    NewsItem(Icons.login, 'Connexion Google corrigée',
        'Sur Android, Google et GitHub vous ramènent directement dans Tontolo. Le retour ne passe plus par une page localhost.',
        'Google sign-in fixed', 'On Android, Google and GitHub return directly to Tontolo instead of a localhost page.',
        mg: 'Fidirana Google voahitsy', mgText: 'Amin’ny Android, mamerina anao mivantana ao amin’i Tontolo i Google sy GitHub fa tsy amin’ny pejy localhost.'),
  ],
  '0.4.6': [
    NewsItem(Icons.forum_outlined, 'Chaque discussion garde son fil',
        'Tontolo répond toujours à la demande de la discussion ouverte, même longue, avec des images, des vidéos et des changements de modèle. Les autres discussions du dossier et la mémoire passent après.',
        'Every chat keeps its thread', 'Tontolo always answers the request of the open chat, even a long one with images, videos and model switches. Other chats in the folder and the memory come after.',
        mg: 'Mitazona ny tadiny ny resaka tsirairay', mgText: 'Mamaly ny fangatahana ao amin\'ny resaka misokatra foana i Tontolo, na lava aza, misy sary, horonan-tsary ary fiovan\'ny modely. Aorian\'izany vao ny resaka hafa ao amin\'ny lahatahiry sy ny fahatsiarovana.'),
  ],
  '0.4.5': [
    NewsItem(Icons.replay, 'Créations plus fiables',
        'Si le modèle qui rédige un fichier tarde ou ne répond plus, Tontolo réessaie automatiquement avec un autre ; en cas d\'échec, la raison est affichée.',
        'More reliable creations', 'If the model writing a file is slow or stops answering, Tontolo retries with another one; if it still fails, the reason is shown.',
        mg: 'Famoronana azo antoka kokoa', mgText: 'Raha miadana na tsy mamaly intsony ny modely manoratra ny rakitra, manandrana amin\'ny hafa ho azy i Tontolo; raha tsy mety, aseho ny antony.'),
  ],
  '0.4.4': [
    NewsItem(Icons.photo_camera_outlined, 'Votre exercice en photo, corrigé en PDF',
        'Photographiez un exercice et demandez « traite l\'exercice 8, rends la réponse en pdf » : Tontolo lit la photo, rédige la correction et la vérifie.',
        'Your exercise photo, solved as a PDF', 'Photograph an exercise and ask “solve exercise 8, give me a PDF”: Tontolo reads the photo, writes the solution and checks it.',
        mg: 'Sarin\'ny fanazaran-tenanao, voavaha ho PDF', mgText: 'Alaivo sary ny fanazaran-tena ary angataho hoe « vahao ny fanazaran-tena 8, omeo PDF »: vakian\'i Tontolo ny sary, soratany ny vahaolana ary hamarininy.'),
    NewsItem(Icons.travel_explore, 'Des réponses, pas des erreurs',
        'Après plusieurs recherches sur le web, Tontolo répond avec ce qu\'il a trouvé au lieu d\'afficher « nombre maximal d\'étapes ».',
        'Answers, not errors', 'After several web searches, Tontolo answers with what it found instead of showing “maximum steps reached”.',
        mg: 'Valiny fa tsy hadisoana', mgText: 'Aorian\'ny fikarohana maromaro, mamaly amin\'izay hitany i Tontolo fa tsy mampiseho hadisoana.'),
  ],
  '0.4.3': [
    NewsItem(Icons.auto_fix_high_outlined, 'Vos photos, mises en scène',
        '« Mets cette statue sur une place d\'Antananarivo » : la photo est retouchée en gardant le sujet. « Anime-la » anime l\'image que vous venez de créer.',
        'Your photos, staged', '“Put this statue in a square in Antananarivo”: the photo is edited while keeping the subject. “Animate it” animates the image you just made.',
        mg: 'Ny saryanao, apetraka amin\'ny toerana', mgText: '« Apetraho amin\'ny kianja iray eto Antananarivo ity sarivongana ity »: amboarina ny sary nefa tsy ovaina ilay zavatra. « Ampihetsiho » no mampihetsika ny sary vao noforoninao.'),
    NewsItem(Icons.edit_note, 'Modifiez vos fichiers',
        'Après une carte mentale ou un document, dites « rajoute des exemples » : le même fichier est complété.',
        'Edit your files', 'After a mind map or a document, say “add examples”: the same file is completed.',
        mg: 'Ovay ny rakitrao', mgText: 'Aorian\'ny sarintsaina na rakitra, lazao hoe « ampio ohatra »: fenoina ilay rakitra ihany.'),
  ],
  '0.4.2': [
    NewsItem(Icons.groups_outlined, 'Relecture vraiment croisée',
        'Un fichier ou une réponse n\'est indiqué « relu par » que si un modèle différent l\'a réellement vérifié.',
        'Truly cross-checked', 'A file or answer is marked “reviewed by” only when a different model really checked it.',
        mg: 'Famakiana tena ifanaovana', mgText: 'Tsy lazaina hoe « novakiana » ny rakitra na valiny raha tsy modely hafa no tena nanamarina azy.'),
  ],
  '0.4.1': [
    NewsItem(Icons.translate, 'Toujours dans votre langue',
        'Tontolo répond dans la langue de votre message, quiz et fiches compris.',
        'Always in your language', 'Tontolo replies in the language of your message, quizzes and flashcards included.',
        mg: 'Amin\'ny fiteninao foana', mgText: 'Mamaly amin\'ny fitenin\'ny hafatrao i Tontolo, ao anatin\'izany ny quiz sy ny karatra.'),
  ],
  '0.4.0': [
    NewsItem(Icons.note_add_outlined, 'Tontolo crée vos fichiers',
        'Demandez un document Word, un PDF, un tableau Excel, une présentation PowerPoint, une carte mentale ou un graphique : le fichier est vérifié puis corrigé avant de vous être donné.',
        'Tontolo creates your files', 'Ask for a Word document, a PDF, an Excel sheet, a PowerPoint deck, a mind map or a chart: the file is checked and fixed before you get it.',
        mg: 'Mamorona ny rakitrao i Tontolo', mgText: 'Angataho rakitra Word, PDF, Excel, PowerPoint, sarintsaina na sary fanoharana: hamarinina sy ahitsy alohan\'ny homena anao ny rakitra.'),
    NewsItem(Icons.groups_outlined, 'Une équipe de modèles',
        'Pour les maths, le code et les fichiers, un second modèle vérifie le travail du premier et signale les erreurs.',
        'A team of models', 'For maths, code and files, a second model checks the first one\'s work and points out mistakes.',
        mg: 'Ekipan\'ny modely', mgText: 'Ho an\'ny matematika, kaody ary rakitra, misy modely faharoa manamarina ny asan\'ny voalohany ary manondro ny diso.'),
    NewsItem(Icons.school_outlined, 'Apprendre, en plus simple',
        'Quatre grandes actions et un tuteur qui ne donne jamais la réponse : il te guide pas à pas jusqu\'à ce que tu la trouves.',
        'Learn, made simpler', 'Four big actions and a tutor that never gives the answer: it guides you step by step until you find it.',
        mg: 'Mianatra, tsotra kokoa', mgText: 'Asa lehibe efatra sy mpanoro tsy manome ny valiny mihitsy: mitarika anao dingana tsirairay mandra-pahitanao azy.'),
  ],
  '0.3.0': [
    NewsItem(Icons.school_outlined, 'Mode Apprendre',
        'Touchez « Apprendre » en haut : un tuteur qui guide pas à pas selon votre niveau, sans faire les devoirs à votre place, avec quiz interactifs et fiches de révision.',
        'Learn mode', 'Tap “Learn” at the top: a tutor that guides you step by step for your level, without doing your homework, with interactive quizzes and flashcards.',
        mg: 'Fomba Mianatra', mgText: 'Tsindrio ny « Mianatra » eo ambony: mpanoro manoro lalana dingana tsirairay araka ny ambaratonganao, tsy manao ny entimodinao, misy quiz sy karatra famerenana.'),
    NewsItem(Icons.move_to_inbox_outlined, 'Continuez une discussion de Claude ou ChatGPT',
        'Collez le lien de partage (claude.ai/share/…, chatgpt.com/share/…) dans le chat : la discussion est importée et vous la continuez ici.',
        'Continue a Claude or ChatGPT chat', 'Paste the share link (claude.ai/share/…, chatgpt.com/share/…) into the chat: it is imported and you continue it here.',
        mg: 'Tohizo ny resaka avy amin\'ny Claude na ChatGPT', mgText: 'Apetaho ao amin\'ny resaka ny rohy fizarana (claude.ai/share/…, chatgpt.com/share/…): tafiditra ny resaka ary tohizanao eto.'),
    NewsItem(Icons.sync_lock_outlined, 'Compte et synchronisation chiffrée',
        'Facultatif : connectez-vous avec Google ou GitHub pour retrouver discussions, mémoires et clés sur tous vos appareils. Chiffré avec votre phrase secrète.',
        'Account and encrypted sync', 'Optional: sign in with Google or GitHub to get chats, memories and keys on all your devices. Encrypted with your secret phrase.',
        mg: 'Kaonty sy fampifanarahana voaaro', mgText: 'Tsy voatery: midira amin\'ny Google na GitHub mba hahitana ny resaka, ny fahatsiarovana ary ny fanalahidy amin\'ny fitaovanao rehetra. Voaaro amin\'ny fehezanteny miafinao.'),
    NewsItem(Icons.auto_awesome_outlined, 'Meilleurs choix automatiques',
        'Images avec FLUX et Stable Diffusion en plus de Pollinations, modèle choisi selon le sujet de la discussion, aide pas à pas pour chaque clé, modèles payants simples avec plafond.',
        'Smarter automatic choices', 'Images with FLUX and Stable Diffusion besides Pollinations, model chosen from the chat topic, step-by-step help for every key, simple paid models with a cap.',
        mg: 'Safidy ho azy tsara kokoa', mgText: 'Sary amin\'ny FLUX sy Stable Diffusion ankoatra ny Pollinations, modely voafidy araka ny lohahevitry ny resaka, torolalana ho an\'ny fanalahidy tsirairay, modely mandoa tsotra misy fetra.'),
  ],
  '0.2.11': [
    NewsItem(Icons.description_outlined, 'Questions sur vos documents',
        'Joignez un PDF ou un texte (bouton +) : Tontolo répond en citant les pages.',
        'Ask about your documents', 'Attach a PDF or text file (+ button): Tontolo answers and cites the pages.',
        mg: 'Fanontaniana momba ny rakitrao', mgText: 'Ampiraiketo PDF na lahatsoratra (bokotra +): mamaly i Tontolo ary manonona ny pejy.'),
    NewsItem(Icons.folder_outlined, 'Dossiers, recherche et partage',
        'Rangez vos discussions dans des dossiers, retrouvez un passage par la recherche, partagez une discussion en page web.',
        'Folders, search and sharing', 'Sort chats into folders, find any passage with search, share a chat as a web page.',
        mg: 'Lahatahiry, fikarohana ary fizarana', mgText: 'Alaharo ao anaty lahatahiry ny resakao, tadiavo izay andalana tianao, zarao ho pejy tranonkala ny resaka.'),
    NewsItem(Icons.offline_bolt_outlined, 'Modèles sur l\'appareil',
        'Avec Ollama ou llama.cpp installé, Tontolo répond même sans Internet.',
        'On-device models', 'With Ollama or llama.cpp installed, Tontolo answers even without Internet.',
        mg: 'Modely ao amin\'ny fitaovana', mgText: 'Raha misy Ollama na llama.cpp, mamaly i Tontolo na tsy misy Internet aza.'),
  ],
  '0.2.10': [
    NewsItem(Icons.brush_outlined, 'Les demandes d\'image ne partent plus vers le texte',
